101			if err == nil {
102				fmt.Printf("snapshot %s created with %d entries\n", snap.Name, len(snap.Entries))
103			}
104			return err
105		case "list":
106			infos, err := store.ListSnapshots()
107			if err != nil {
108				return err
109			}
110			for _, info := range infos {
111				fmt.Printf("%s\t%d\n", info.Name, info.Count)
112			}
113			return nil
114		case "restore":
115			if err := store.RestoreSnapshot(*name); err != nil {
116				return err
117			}
118			fmt.Printf("restored snapshot %s\n", *name)
119			return nil
120		case "export":
121			result, err := store.ExportSnapshot(*name, *base, *output)
122			if err != nil {
123				return err
124			}
125			fmt.Printf("exported snapshot %s with %d entries, %d objects\n", result.Name, result.Entries, result.Objects)
126			return nil
127		case "import":
128			result, err := store.ImportSnapshot(*file)
129			if err != nil {
130				return err
131			}
132			fmt.Printf("imported snapshot %s with %d entries, %d new objects\n", result.Name, result.Entries, result.NewObjects)
133			return nil
134		default:
135			return fmt.Errorf("unknown snapshot command %q", sub)
136		}
