1	package vault
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/base64"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"sort"
13	)
14	
15	// Package format:
16	//
17	// A snapshot package is an indented JSON document that moves one complete
18	// snapshot, together with whatever content objects it needs, between
19	// repositories. A full package carries every referenced object; an
20	// incremental package records a Base and only carries objects the base
21	// snapshot does not reference. Either way Snapshot always holds the complete
22	// target mapping — additions, overwrites, and deletions relative to the base
23	// are expressed solely by that mapping.
24	//
25	//	{
26	//	  "format": "artifact-vault-snapshot",
27	//	  "version": 1,
28	//	  "snapshot": { "name": "...", "entries": { ... } },
29	//	  "base": { "name": "...", "entries": { ... } },     // delta only, optional
30	//	  "objects": [
31	//	    { "digest": "<sha256 hex>", "size": 123, "data": "<base64>" }
32	//	  ]
33	//	}
34	//
35	// An object's SHA-256 digest over its decoded bytes is also its filename
36	// inside objects/, so no package record can name a destination outside that
37	// directory.
38	const (
39		packageFormat  = "artifact-vault-snapshot"
40		packageVersion = 1
41	)
42	
43	// PackageObject is one content object carried by a package.
44	type PackageObject struct {
45		Digest string `json:"digest"`
46		Size   int64  `json:"size"`
47		Data   string `json:"data"`
48	}
49	
50	// Package is the on-disk snapshot transfer format.
51	type Package struct {
52		Format   string          `json:"format"`
53		Version  int             `json:"version"`
54		Snapshot Snapshot        `json:"snapshot"`
55		Base     *Snapshot       `json:"base,omitempty"`
56		Objects  []PackageObject `json:"objects"`
57	}
58	
59	// rejectDuplicateKeys walks the raw JSON token stream and fails if any object
60	// lists the same key twice. encoding/json otherwise keeps only the last
61	// occurrence, which could hide a duplicate object or entry behind an earlier,
62	// validated one.
63	func rejectDuplicateKeys(data []byte) error {
64		type frame struct {
65			object    bool
66			keys      map[string]struct{}
67			expectKey bool
68		}
69		dec := json.NewDecoder(bytes.NewReader(data))
70		var stack []frame
71		for {
72			tok, err := dec.Token()
73			if err == io.EOF {
74				return nil
75			}
76			if err != nil {
77				return err
78			}
79			switch t := tok.(type) {
80			case json.Delim:
81				switch t {
82				case '{':
83					stack = append(stack, frame{object: true, keys: map[string]struct{}{}, expectKey: true})
84				case '[':
85					stack = append(stack, frame{object: false})
86				case '}', ']':
87					if len(stack) == 0 {
88						return errors.New("unbalanced JSON delimiters")
89					}
90					stack = stack[:len(stack)-1]
91					// The composite value just consumed completes an entry in the
92					// enclosing object, so its next string is another key.
93					if len(stack) > 0 && stack[len(stack)-1].object {
94						stack[len(stack)-1].expectKey = true
95					}
96				}
97			case string:
98				if len(stack) > 0 && stack[len(stack)-1].object {
99					f := &stack[len(stack)-1]
100					if f.expectKey {
101						if _, dup := f.keys[t]; dup {
102							return fmt.Errorf("duplicate key %q", t)
103						}
104						f.keys[t] = struct{}{}
105						f.expectKey = false
106					} else {
107						f.expectKey = true
108					}
109				}
110			default:
111				// Primitive value in an object frame: the next string token is a key.
112				if len(stack) > 0 && stack[len(stack)-1].object {
113					stack[len(stack)-1].expectKey = true
114				}
115			}
116		}
117	}
118	
119	// marshalPackage serializes the package as indented JSON.
120	func marshalPackage(pkg *Package) ([]byte, error) {
121		data, err := json.MarshalIndent(pkg, "", "  ")
122		if err != nil {
123			return nil, err
124		}
125		return append(data, '\n'), nil
126	}
127	
128	// decodePackage parses a package without touching any repository. It enforces
129	// every self-contained invariant the specification places on a package:
130	//
131	//   - known format and version;
132	//   - snapshot (and base, if present) records are complete and valid:
133	//     snapshot name legal, entries keyed by their recorded name, legal names,
134	//     64 lowercase-hex digests, non-negative sizes;
135	//   - every object digest is valid and unique, the base64 data decodes, and
136	//     its length and SHA-256 match the record;
137	//   - the object set carries exactly the objects required by the snapshot
138	//     mapping minus the base mapping (all of them for a full package),
139	//     neither omitting a referenced digest nor carrying an unreferenced one.
140	//
141	// Cross-repository checks (an existing base snapshot, objects already present
142	// in the destination, name collisions) are performed later by import, which
143	// has the destination in hand.
144	func decodePackage(data []byte) (*Package, error) {
145		// encoding/json silently keeps the last value when an object lists a key
146		// twice; that would let a package hide a duplicate entry or overwrite a
147		// structural field. Reject any such document before decoding it.
148		if err := rejectDuplicateKeys(data); err != nil {
149			return nil, fmt.Errorf("invalid package: %w", err)
150		}
151		dec := json.NewDecoder(bytes.NewReader(data))
152		dec.DisallowUnknownFields()
153		var raw struct {
154			Format   string             `json:"format"`
155			Version  int                `json:"version"`
156			Snapshot Snapshot           `json:"snapshot"`
157			Base     *Snapshot          `json:"base,omitempty"`
158			Objects  *[]json.RawMessage `json:"objects"`
159		}
160		if err := dec.Decode(&raw); err != nil {
161			return nil, fmt.Errorf("invalid package: %w", err)
162		}
163		if tok, err := dec.Token(); err != io.EOF {
164			if err == nil {
165				return nil, fmt.Errorf("invalid package: unexpected trailing content after top-level value (%v)", tok)
166			}
167			return nil, fmt.Errorf("invalid package: %w", err)
168		}
169		if raw.Format != packageFormat {
170			return nil, fmt.Errorf("invalid package: unknown format %q", raw.Format)
171		}
172		if raw.Version != packageVersion {
173			return nil, fmt.Errorf("invalid package: unsupported version %d (supported: %d)", raw.Version, packageVersion)
174		}
175		if raw.Objects == nil {
176			return nil, errors.New("invalid package: missing objects array")
177		}
178	
179		pkg := &Package{Format: raw.Format, Version: raw.Version, Objects: []PackageObject{}}
180		if err := validateSnapshotRecord("snapshot", raw.Snapshot); err != nil {
181			return nil, err
182		}
183		pkg.Snapshot = raw.Snapshot
184		if raw.Base != nil {
185			if err := validateSnapshotRecord("base", *raw.Base); err != nil {
186				return nil, err
187			}
188			pkg.Base = raw.Base
189		}
190	
191		seen := map[string]struct{}{}
192		for i, item := range *raw.Objects {
193			var obj PackageObject
194			odec := json.NewDecoder(bytes.NewReader(item))
195			odec.DisallowUnknownFields()
196			if err := odec.Decode(&obj); err != nil {
197				return nil, fmt.Errorf("invalid package: object %d: %w", i, err)
198			}
199			if _, err := odec.Token(); err != io.EOF {
200				if err == nil {
201					return nil, fmt.Errorf("invalid package: object %d: trailing content", i)
202				}
203				return nil, fmt.Errorf("invalid package: object %d: %w", i, err)
204			}
205			if !isDigest(obj.Digest) {
206				return nil, fmt.Errorf("invalid package: object %d: digest %q is not 64 lowercase hex characters", i, obj.Digest)
207			}
208			if obj.Size < 0 {
209				return nil, fmt.Errorf("invalid package: object %s has negative size %d", obj.Digest, obj.Size)
210			}
211			if _, dup := seen[obj.Digest]; dup {
212				return nil, fmt.Errorf("invalid package: duplicate object %s", obj.Digest)
213			}
214			seen[obj.Digest] = struct{}{}
215			content, err := base64.StdEncoding.DecodeString(obj.Data)
216			if err != nil {
217				return nil, fmt.Errorf("invalid package: object %s: data is not valid base64: %w", obj.Digest, err)
218			}
219			if int64(len(content)) != obj.Size {
220				return nil, fmt.Errorf("invalid package: object %s: data is %d bytes, record says %d", obj.Digest, len(content), obj.Size)
221			}
222			sum := sha256.Sum256(content)
223			if actual := hex.EncodeToString(sum[:]); actual != obj.Digest {
224				return nil, fmt.Errorf("invalid package: object %s: content checksum is %s", obj.Digest, actual)
225			}
226			pkg.Objects = append(pkg.Objects, obj)
227		}
228	
229		needed := digestsReferenced(pkg.Snapshot.Entries)
230		if pkg.Base != nil {
231			for digest := range digestsReferenced(pkg.Base.Entries) {
232				delete(needed, digest)
233			}
234		}
235		carried := map[string]struct{}{}
236		for _, obj := range pkg.Objects {
237			carried[obj.Digest] = struct{}{}
238		}
239		for digest := range needed {
240			if _, ok := carried[digest]; !ok {
241				return nil, fmt.Errorf("invalid package: required object %s is missing from the package", digest)
242			}
243		}
244		for digest := range carried {
245			if _, ok := needed[digest]; !ok {
246				return nil, fmt.Errorf("invalid package: object %s is not referenced by the target mapping", digest)
247			}
248		}
249		return pkg, nil
250	}
251	
252	// validateSnapshotRecord validates one embedded snapshot the same way restore
253	// and gc validate on-disk snapshots.
254	func validateSnapshotRecord(scope string, snap Snapshot) error {
255		if err := validateName(snap.Name); err != nil {
256			return fmt.Errorf("invalid package: %s snapshot name %q is not a legal snapshot name", scope, snap.Name)
257		}
258		if snap.Entries == nil {
259			return fmt.Errorf("invalid package: %s snapshot %q is missing its entries mapping", scope, snap.Name)
260		}
261		for key, entry := range snap.Entries {
262			if err := validateEntryRecord(key, entry); err != nil {
263				return fmt.Errorf("invalid package: %s snapshot %q: %w", scope, snap.Name, err)
264			}
265		}
266		return nil
267	}
268	
269	// digestsReferenced returns the set of object digests referenced by a set of
270	// snapshot entries. Multiple entries may share one digest.
271	func digestsReferenced(entries map[string]Entry) map[string]struct{} {
272		digests := make(map[string]struct{}, len(entries))
273		for _, entry := range entries {
274			digests[entry.Digest] = struct{}{}
275		}
276		return digests
277	}
278	
279	// objectContent is a decoded package object kept in memory during import.
280	type objectContent struct {
281		digest  string
282		size    int64
283		content []byte
284	}
285	
286	// materialize decodes the base64 payloads of every carried object into
287	// memory. Import holds the objects while it stages them; packages are
288	// bounded artifacts meant to be copied between machines.
289	func (p *Package) materialize() ([]objectContent, error) {
290		objects := make([]objectContent, 0, len(p.Objects))
291		// Sort so staging order (and any error message) is deterministic.
292		ordered := append([]PackageObject(nil), p.Objects...)
293		sort.Slice(ordered, func(i, j int) bool { return ordered[i].Digest < ordered[j].Digest })
294		for _, obj := range ordered {
295			content, err := base64.StdEncoding.DecodeString(obj.Data)
296			if err != nil {
297				return nil, fmt.Errorf("object %s: %w", obj.Digest, err)
298			}
299			objects = append(objects, objectContent{digest: obj.Digest, size: obj.Size, content: content})
300		}
301		return objects, nil
302	}
