1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"strings"
13		"syscall"
14	)
15	
16	// Get downloads the artifact recorded under name in the current index to the
17	// output path. Nothing is delivered unless the stored object is complete and
18	// the destination is safe:
19	//
20	//   - the index and the selected record must be usable (parseable, with a
21	//     name mapping, the recorded name matching its key, a 64-character
22	//     lowercase-hex digest, and a non-negative size);
23	//   - the object must exist, be a regular file, and its actual size and
24	//     SHA-256 must match the record;
25	//   - the output must be outside the repository (including through a
26	//     symlinked parent), its parent directory must exist, and an existing
27	//     output must be a regular file that is not a hard link to any repository
28	//     file.
29	//
30	// The object is streamed and hashed into a temporary file beside the output;
31	// only after the complete, verified bytes are flushed is the output renamed
32	// into place. A failed download therefore leaves an existing output
33	// byte-for-byte intact and a missing output absent; an interrupted process
34	// leaves at most an unreferenced temporary file that a later download
35	// replaces without manual cleanup.
36	func (s *Store) Get(name, output string) error {
37		if err := validateName(name); err != nil {
38			return err
39		}
40		if output == "" {
41			return errors.New("output is required")
42		}
43		return s.withLock(false, func() error {
44			return s.getLocked(name, output)
45		})
46	}
47	
48	func (s *Store) getLocked(name, output string) error {
49		// The index and every record it holds must be usable before any object is
50		// read. A missing or malformed record is reported as record corruption,
51		// distinct from a name that simply does not exist.
52		idx, err := s.loadStrict()
53		if err != nil {
54			return fmt.Errorf("artifact %q: record is corrupted: %w", name, err)
55		}
56		for key, entry := range idx.Entries {
57			if err := validateEntryRecord(key, entry); err != nil {
58				return fmt.Errorf("artifact %q: record is corrupted: %w", name, err)
59			}
60		}
61		entry, ok := idx.Entries[name]
62		if !ok {
63			return fmt.Errorf("artifact %q not found", name)
64		}
65	
66		absOut, mode, err := s.checkOutputSafe(output)
67		if err != nil {
68			return fmt.Errorf("artifact %q: %w", name, err)
69		}
70		if err := s.downloadObject(entry, absOut, mode); err != nil {
71			return fmt.Errorf("artifact %q: %w", name, err)
72		}
73		return nil
74	}
75	
76	// checkOutputSafe validates the destination of a download without opening the
77	// object. It returns the absolute output path and the permission bits a new
78	// file should have.
79	func (s *Store) checkOutputSafe(output string) (string, os.FileMode, error) {
80		absOut, err := filepath.Abs(output)
81		if err != nil {
82			return "", 0, fmt.Errorf("output %q: cannot resolve path: %w", output, err)
83		}
84		mode := os.FileMode(0o644)
85		if info, err := os.Lstat(absOut); err == nil {
86			// Symlinks are never followed; anything that is not a regular file
87			// (directory, device, socket, ...) is refused.
88			if info.Mode()&os.ModeSymlink != 0 {
89				return "", 0, fmt.Errorf("output %q is a symbolic link", output)
90			}
91			if !info.Mode().IsRegular() {
92				return "", 0, fmt.Errorf("output %q is not a regular file", output)
93			}
94			mode = info.Mode().Perm()
95		} else if !errors.Is(err, os.ErrNotExist) {
96			return "", 0, err
97		}
98	
99		absRoot, err := filepath.Abs(s.root)
100		if err != nil {
101			return "", 0, fmt.Errorf("cannot resolve repository root: %w", err)
102		}
103		resolvedRoot, err := filepath.EvalSymlinks(absRoot)
104		if err != nil {
105			return "", 0, fmt.Errorf("cannot resolve repository root: %w", err)
106		}
107		// Path-based containment first: this works even when the output or its
108		// parent does not exist yet, so a not-yet-created destination inside the
109		// repository is refused before any symlink is followed.
110		if rel, err := filepath.Rel(resolvedRoot, absOut); err == nil {
111			if rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
112				return "", 0, fmt.Errorf("output %q is inside the repository", output)
113			}
114		}
115		// Resolve every symlink in the path so a destination that reaches into the
116		// repository through a symlinked parent cannot hide.
117		resolved, err := filepath.EvalSymlinks(absOut)
118		if err != nil {
119			if !errors.Is(err, os.ErrNotExist) {
120				return "", 0, fmt.Errorf("output %q: cannot resolve path: %w", output, err)
121			}
122			// The final component may simply not exist yet; its parent must.
123			parent := filepath.Dir(absOut)
124			resolvedParent, err := filepath.EvalSymlinks(parent)
125			if err != nil {
126				return "", 0, fmt.Errorf("output %q: parent directory is not accessible: %w", output, err)
127			}
128			resolved = filepath.Join(resolvedParent, filepath.Base(absOut))
129		}
130		rel, err := filepath.Rel(resolvedRoot, resolved)
131		if err != nil {
132			return "", 0, fmt.Errorf("output %q: %w", output, err)
133		}
134		// A path inside the repository resolves from the root without ever going
135		// up: rel is "." or a descendant. Only a rel that is exactly ".." or
136		// starts with "../" leaves the repository.
137		if rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
138			return "", 0, fmt.Errorf("output %q is inside the repository", output)
139		}
140	
141		if err := s.checkOutputNotRepoHardlink(absOut, output); err != nil {
142			return "", 0, err
143		}
144		return absOut, mode, nil
145	}
146	
147	// checkOutputNotRepoHardlink refuses an existing output that is a hard link to
148	// any repository file (the index, the lock, an object, or a snapshot record).
149	// Replacing such a link would rewrite the repository file's contents through
150	// the link.
151	func (s *Store) checkOutputNotRepoHardlink(absOut, output string) error {
152		info, err := os.Lstat(absOut)
153		if errors.Is(err, os.ErrNotExist) {
154			return nil
155		}
156		if err != nil {
157			return err
158		}
159		outID, ok := fileIDOf(info)
160		if !ok {
161			return nil
162		}
163		for id, repoPath := range s.repoFileIDs() {
164			if id == outID {
165				return fmt.Errorf("output %q is a hard link to repository file %q", output, repoPath)
166			}
167		}
168		return nil
169	}
170	
171	type fileID struct {
172		dev uint64
173		ino uint64
174	}
175	
176	func fileIDOf(info os.FileInfo) (fileID, bool) {
177		st, ok := info.Sys().(*syscall.Stat_t)
178		if !ok {
179			return fileID{}, false
180		}
181		return fileID{dev: uint64(st.Dev), ino: uint64(st.Ino)}, true
182	}
183	
184	// repoFileIDs collects the device/inode identity of every repository file an
185	// output must not be hard-linked to: the index, the lock, every object, and
186	// every snapshot record.
187	func (s *Store) repoFileIDs() map[fileID]string {
188		ids := map[fileID]string{}
189		add := func(path string) {
190			info, err := os.Lstat(path)
191			if err != nil {
192				return
193			}
194			if id, ok := fileIDOf(info); ok {
195				ids[id] = path
196			}
197		}
198		add(s.indexPath())
199		add(s.lockPath())
200		if entries, err := os.ReadDir(filepath.Join(s.root, "objects")); err == nil {
201			for _, entry := range entries {
202				add(filepath.Join(s.root, "objects", entry.Name()))
203			}
204		}
205		_ = filepath.WalkDir(s.snapshotsDir(), func(path string, d fs.DirEntry, err error) error {
206			if err == nil && d.Type().IsRegular() {
207				add(path)
208			}
209			return nil
210		})
211		return ids
212	}
213	
214	// downloadObject streams the verified object into a temporary file beside the
215	// output and renames it into place only after the complete bytes match the
216	// record. It never truncates or writes the output directly, and it never
217	// buffers the whole object in memory.
218	func (s *Store) downloadObject(entry Entry, absOut string, mode os.FileMode) error {
219		objPath := s.objectPath(entry.Digest)
220		info, err := os.Lstat(objPath)
221		if err != nil {
222			if errors.Is(err, os.ErrNotExist) {
223				return fmt.Errorf("object %s is missing", entry.Digest)
224			}
225			return fmt.Errorf("cannot stat object %s: %w", entry.Digest, err)
226		}
227		if info.Mode()&os.ModeSymlink != 0 {
228			return fmt.Errorf("object %s is a symbolic link", entry.Digest)
229		}
230		if !info.Mode().IsRegular() {
231			return fmt.Errorf("object %s is not a regular file", entry.Digest)
232		}
233	
234		in, err := os.Open(objPath)
235		if err != nil {
236			return fmt.Errorf("cannot read object %s: %w", entry.Digest, err)
237		}
238		defer in.Close()
239	
240		tmp, err := os.CreateTemp(filepath.Dir(absOut), ".download-*")
241		if err != nil {
242			return fmt.Errorf("cannot create temporary file for output: %w", err)
243		}
244		tmpName := tmp.Name()
245		committed := false
246		defer func() {
247			if !committed {
248				os.Remove(tmpName)
249			}
250		}()
251	
252		if err := tmp.Chmod(mode); err != nil {
253			tmp.Close()
254			return fmt.Errorf("cannot prepare output file: %w", err)
255		}
256		hash := sha256.New()
257		n, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
258		readErr := in.Close()
259		if copyErr != nil {
260			tmp.Close()
261			return fmt.Errorf("cannot read object %s: %w", entry.Digest, copyErr)
262		}
263		if readErr != nil {
264			tmp.Close()
265			return fmt.Errorf("cannot read object %s: %w", entry.Digest, readErr)
266		}
267		if n != entry.Size {
268			tmp.Close()
269			return fmt.Errorf("object %s is corrupted: content is %d bytes, record says %d", entry.Digest, n, entry.Size)
270		}
271		if actual := hex.EncodeToString(hash.Sum(nil)); actual != entry.Digest {
272			tmp.Close()
273			return fmt.Errorf("object %s is corrupted: content checksum is %s, want %s", entry.Digest, actual, entry.Digest)
274		}
275		if err := tmp.Sync(); err != nil {
276			tmp.Close()
277			return fmt.Errorf("cannot write output %q: %w", absOut, err)
278		}
279		if err := tmp.Close(); err != nil {
280			return fmt.Errorf("cannot write output %q: %w", absOut, err)
281		}
282		if err := os.Rename(tmpName, absOut); err != nil {
283			return fmt.Errorf("cannot write output %q: %w", absOut, err)
284		}
285		committed = true
286		// Best-effort directory sync so the rename survives a crash; failure here
287		// does not undo an already atomic replacement.
288		if dir, err := os.Open(filepath.Dir(absOut)); err == nil {
289			_ = dir.Sync()
290			_ = dir.Close()
291		}
292		return nil
293	}
