30	// ExportSnapshot writes the named snapshot, together with the content objects
31	// it needs, to output as a portable package.
32	//
33	// Without a base the package is complete: every referenced object is carried,
34	// and a digest shared by several entries is carried once. With base set to the
35	// name of another snapshot in the same repository, the package still records
36	// the target's complete mapping but only carries objects the base does not
37	// reference; an importer can only apply it on top of an identical base.
38	//
39	// Every object the target references is re-read and checked for recorded size
40	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
41	// record or a missing/damaged object never produces a successful package. The
42	// package is assembled in memory and written to a temporary file beside the
43	// destination before an atomic rename: a failed export never creates or
44	// alters the output file.
45	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
46		if err := validateName(name); err != nil {
47			return ExportResult{}, err
48		}
49		if base != "" {
50			if err := validateName(base); err != nil {
51				return ExportResult{}, err
52			}
53		}
54		if output == "" {
55			return ExportResult{}, errors.New("output is required")
56		}
57		var result ExportResult
58		err := s.withLock(true, func() error {
59			if err := s.initLocked(); err != nil {
60				return err
61			}
62			target, err := s.loadSnapshotRecord(name)
63			if err != nil {
64				return err
65			}
66			pkg := &Package{
67				Format:   packageFormat,
68				Version:  packageVersion,
69				Snapshot: target,
70				Objects:  []PackageObject{},
71			}
72			var baseSnap Snapshot
73			if base != "" {
74				var err error
75				baseSnap, err = s.loadSnapshotRecord(base)
76				if err != nil {
77					return fmt.Errorf("cannot use base snapshot: %w", err)
78				}
79				pkg.Base = &baseSnap
80			}
81	
82			// Verify every object the target references, reading each once. This
83			// includes objects the delta omits because the base references them:
84			// certifying the delta requires those to be intact too. Only objects
85			// the base does not reference are carried. Digests are processed in
86			// sorted order so the package layout and any failure message are
87			// deterministic.
88			carry := digestsReferenced(target.Entries)
89			if base != "" {
90				for digest := range digestsReferenced(baseSnap.Entries) {
91					delete(carry, digest)
92				}
93			}
94			for _, digest := range sortedDigests(target.Entries) {
95				content, size, err := s.readVerifiedObject(digest, target.Entries)
96				if err != nil {
97					return fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
98				}
99				if _, included := carry[digest]; !included {
100					continue
101				}
102				pkg.Objects = append(pkg.Objects, PackageObject{
103					Digest: digest,
104					Size:   size,
105					Data:   base64.StdEncoding.EncodeToString(content),
106				})
107			}
108	
109			data, err := marshalPackage(pkg)
110			if err != nil {
111				return err
112			}
113			if err := writeFileAtomic(output, data, ".package-*"); err != nil {
114				return err
115			}
116			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: len(pkg.Objects)}
117			return nil
118		})
119		if err != nil {
120			return ExportResult{}, err
121		}
122		return result, nil
123	}
