125	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
126	// initialized repository.
127	//
128	// Import only adds the package's snapshot and any missing content objects; it
129	// never changes the current name mapping or any existing snapshot or object.
130	// A delta package is accepted only when the destination already contains a
131	// snapshot with the base name and byte-identical entry metadata, and every
132	// object the delta omits is present and intact. Healthy objects already in the
133	// destination are reused; re-importing a package whose snapshot is already
134	// present with identical metadata succeeds without creating a second copy. A
135	// same-named snapshot with different metadata is refused.
136	//
137	// All validation and reuse happens before anything is written. New objects
138	// land as complete files via temp-file-and-rename, and the snapshot record is
139	// renamed into place only after every object the mapping references has been
140	// verified, so a crash or write failure leaves at most unreferenced complete
141	// objects that a later gc removes and a retry succeeds; a partially imported
142	// snapshot can never be observed.
143	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
144		if file == "" {
145			return ImportResult{}, errors.New("file is required")
146		}
147		data, err := os.ReadFile(file)
148		if err != nil {
149			return ImportResult{}, err
150		}
151		pkg, err := decodePackage(data)
152		if err != nil {
153			return ImportResult{}, err
154		}
155		// Import targets an initialized repository; it never creates one the way
156		// mutating artifact commands do.
157		rootInfo, err := os.Stat(s.root)
158		switch {
159		case errors.Is(err, os.ErrNotExist):
160			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
161		case err != nil:
162			return ImportResult{}, err
163		case !rootInfo.IsDir():
164			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
165		}
166		var result ImportResult
167		err = s.withLock(true, func() error {
168			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
169				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
170			} else if err != nil {
171				return err
172			}
173			if err := rejectLinkedDirs(s.root); err != nil {
174				return err
175			}
176	
177			// A delta must sit on an exactly matching base: same snapshot name and
178			// identical entry metadata. A merely same-named snapshot, or objects
179			// that happen to share digests, is not a base.
180			if pkg.Base != nil {
181				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
182				if err != nil {
183					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
184				}
185				if !snapshotsEqual(existing, *pkg.Base) {
186					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
187				}
188				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
189					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
190				}
191			}
192	
193			// A same-named destination snapshot is either identical metadata or a
194			// collision. A collision is refused before anything is staged.
195			targetPath := s.snapshotPath(pkg.Snapshot.Name)
196			identicalSnapshot := false
197			if existing, statErr := os.Lstat(targetPath); statErr == nil {
198				if existing.Mode()&os.ModeSymlink != 0 {
199					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
200				}
201				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
202				if err != nil {
203					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
204				}
205				if !snapshotsEqual(current, pkg.Snapshot) {
206					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
207				}
208				identicalSnapshot = true
209				// Fast path: everything the published snapshot needs is already
210				// present and healthy, so the import is a no-op.
211				if s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries) == nil {
212					result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
213					return nil
214				}
215				// Otherwise fall through: a carried object that is merely missing
216				// can be staged to complete an earlier interrupted import, while a
217				// damaged existing object still aborts below.
218			} else if !errors.Is(statErr, os.ErrNotExist) {
219				return statErr
220			}
221	
222			objects, err := pkg.materialize()
223			if err != nil {
224				return err
225			}
226	
227			// Phase 1, no writes: classify every carried object. Existing files
228			// must be healthy and are reused; a damaged one aborts the import and
229			// is reported by digest.
230			toAdd := make([]objectContent, 0, len(objects))
231			for _, obj := range objects {
232				path := s.objectPath(obj.digest)
233				info, err := os.Lstat(path)
234				switch {
235				case err == nil:
236					if info.Mode()&os.ModeSymlink != 0 {
237						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
238					}
239					if !info.Mode().IsRegular() {
240						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
241					}
242					if _, _, err := s.readVerifiedObject(obj.digest, pkg.Snapshot.Entries); err != nil {
243						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
244					}
245				case errors.Is(err, os.ErrNotExist):
246					toAdd = append(toAdd, obj)
247				default:
248					return err
249				}
250			}
251	
252			// Phase 2: stage missing objects as complete, content-addressed files.
253			// A failure here leaves only unreferenced complete objects behind; a
254			// retry reuses them and finishes the import.
255			for _, obj := range toAdd {
256				if err := s.stageObject(obj.digest, obj.content); err != nil {
257					return err
258				}
259			}
260	
261			// Phase 3: the published mapping must be fully restorable. This covers
262			// reused objects, newly staged ones, and everything omitted by a delta.
263			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
264				return err
265			}
266	
267			// Phase 4: publish the snapshot record last (unless an identical one is
268			// already published). This rename is the commit point; before it a new
269			// imported snapshot simply does not exist.
270			if !identicalSnapshot {
271				if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
272					return err
273				}
274			}
275			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
276			return nil
277		})
278		if err != nil {
279			return ImportResult{}, err
280		}
281		return result, nil
282	}
