284	// loadSnapshotRecord reads and fully validates one stored snapshot: it must
285	// parse, carry a non-null entries mapping, record the same name it is filed
286	// under, and contain only valid entry records.
287	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
288		path := s.snapshotPath(name)
289		info, err := os.Lstat(path)
290		if errors.Is(err, os.ErrNotExist) {
291			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
292		}
293		if err != nil {
294			return Snapshot{}, err
295		}
296		if info.Mode()&os.ModeSymlink != 0 {
297			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
298		}
299		if !info.Mode().IsRegular() {
300			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
301		}
302		data, err := os.ReadFile(path)
303		if err != nil {
304			return Snapshot{}, err
305		}
306		var snap Snapshot
307		if err := json.Unmarshal(data, &snap); err != nil {
308			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
309		}
310		if snap.Entries == nil {
311			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: missing entries mapping", name)
312		}
313		if snap.Name != name {
314			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: recorded name %q does not match its location", name, snap.Name)
315		}
316		for key, entry := range snap.Entries {
317			if err := validateEntryRecord(key, entry); err != nil {
318				return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
319			}
320		}
321		return snap, nil
322	}
323	
324	// verifyReferencedObjects checks each distinct referenced digest once against
325	// the stored object's size and SHA-256.
326	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
327		for _, digest := range sortedDigests(entries) {
328			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
329				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
330			}
331		}
332		return nil
333	}
334	
335	// readVerifiedObject reads a content object and returns its bytes, confirming
336	// its SHA-256 digest and the size recorded for it in the given entries.
337	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
338		path := s.objectPath(digest)
339		info, err := os.Lstat(path)
340		if err != nil {
341			return nil, 0, err
342		}
343		if info.Mode()&os.ModeSymlink != 0 {
344			return nil, 0, errors.New("object path is a symbolic link")
345		}
346		if !info.Mode().IsRegular() {
347			return nil, 0, errors.New("object path is not a regular file")
348		}
349		content, err := os.ReadFile(path)
350		if err != nil {
351			return nil, 0, err
352		}
353		sum := sha256.Sum256(content)
354		if actual := hex.EncodeToString(sum[:]); actual != digest {
355			return nil, 0, fmt.Errorf("content checksum is %s", actual)
356		}
357		// Every entry referencing this digest must agree on the size; a content
358		// hash fixes the byte count, so a disagreement is a corrupt record.
359		for _, entry := range entries {
360			if entry.Digest == digest && int64(len(content)) != entry.Size {
361				return nil, 0, fmt.Errorf("content is %d bytes, record for %q says %d", len(content), entry.Name, entry.Size)
362			}
363		}
364		return content, int64(len(content)), nil
365	}
366	
367	// stageObject writes one missing object to a temp file and renames it into
368	// place. The content digest was verified when the package was decoded, so the
369	// final file is complete before it ever appears under its digest name.
370	func (s *Store) stageObject(digest string, content []byte) error {
371		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
372		if err != nil {
373			return err
374		}
375		tmpName := tmp.Name()
376		defer os.Remove(tmpName)
377		if _, err := tmp.Write(content); err != nil {
378			tmp.Close()
379			return fmt.Errorf("object %s: %w", digest, err)
380		}
381		if err := tmp.Close(); err != nil {
382			return fmt.Errorf("object %s: %w", digest, err)
383		}
384		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
385			return fmt.Errorf("object %s: %w", digest, err)
386		}
387		return nil
388	}
389	
390	// rejectLinkedDirs makes sure an import can never stage files outside the
391	// repository through a replaced objects or snapshots directory.
392	func rejectLinkedDirs(root string) error {
393		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
394			if err := ensureRealDir(dir); err != nil {
395				return err
396			}
397		}
398		return nil
399	}
400	
401	// writeFileAtomic writes data to a temporary file in the destination's
402	// directory and renames it over dest only after a complete flush. An existing
403	// destination is left untouched on any earlier failure.
404	func writeFileAtomic(dest string, data []byte, pattern string) error {
