	}
	if err := filepath.WalkDir(s.snapshotsDir(), func(path string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if d.IsDir() {
			return nil
		}
		return add(path)
	}); err != nil {
		return nil, fmt.Errorf("snapshots: %w", err)
	}
